SELECT MAX(aoi), MIN(aoi), AVG(aoi) FROM (
    SELECT observstation, 
           ROUND((atmostransparency * (1 - humidityrate/100.0) * (1 - 0.02 * windspeedms))::numeric, 4) AS aoi
    FROM observatories
) t;

SELECT json_agg(
    json_build_object(
        'station_name', TRIM(observstation),
        'aoi_value', ROUND((atmostransparency * (1 - humidityrate/100.0) * (1 - 0.02 * windspeedms))::numeric, 4),
        'lunar_factors', json_build_object(
            'lunar_stage', lunarstage,
            'lunar_distance', lunardistdeg
        ),
        'solar_condition', solarstatus
    )
) FROM observatories LIMIT 1;
